CREATE TEMP TABLE project_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.ok(n text,v boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'Project assertion: %',n;END IF;INSERT INTO project_checks VALUES(n);END;$$;
CREATE FUNCTION pg_temp.fails(n text,s text,code text) RETURNS void LANGUAGE plpgsql AS $$DECLARE failed boolean:=false;BEGIN BEGIN EXECUTE s;EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>code THEN RAISE;END IF;failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Missing expected failure: %',n;END IF;INSERT INTO project_checks VALUES(n);END;$$;
CREATE FUNCTION pg_temp.project_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action=current_setting('bedos.project_fail_action',true) THEN RAISE EXCEPTION 'Synthetic project audit failure' USING ERRCODE='23514';END IF;RETURN NEW;END;$$;
CREATE TRIGGER m7_rollback_audit_failure BEFORE INSERT ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION pg_temp.project_audit_failure();
DO $test$
DECLARE a uuid:=gen_random_uuid();cm uuid:=gen_random_uuid();customer uuid:=gen_random_uuid();finance uuid:=gen_random_uuid();inactive uuid:=gen_random_uuid();p uuid;other uuid;c uuid;svc uuid;stage uuid;stage2 uuid;op uuid;image uuid;op2 uuid;image2 uuid;key uuid:=gen_random_uuid();v integer;data jsonb;res jsonb;old jsonb;proof jsonb;r text;t text;priv text;s text;audits bigint;
BEGIN
 INSERT INTO public.permissions(name) VALUES('projects.view'),('projects.manage') ON CONFLICT(name) DO NOTHING;
 INSERT INTO public.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM public.roles r CROSS JOIN public.permissions p WHERE r.name IN('administrator','content_manager') AND p.name IN('projects.view','projects.manage') ON CONFLICT DO NOTHING;
 INSERT INTO public.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM public.roles r CROSS JOIN public.permissions p WHERE r.name='customer' AND p.name='projects.view' ON CONFLICT DO NOTHING;
 INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT x,x||'@module7-sql.invalid','{}'::jsonb FROM unnest(ARRAY[a,cm,customer,finance,inactive]) x;
 UPDATE public.profiles SET account_status='active',role_id=(SELECT id FROM public.roles WHERE name='customer') WHERE id IN(a,cm,customer,finance,inactive);
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='administrator') WHERE id=a;
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='content_manager') WHERE id IN(cm,inactive);
 UPDATE public.profiles SET account_status='suspended' WHERE id=inactive;
 UPDATE public.profiles SET role_id=(SELECT id FROM public.roles WHERE name='finance') WHERE id=finance;
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  FOREACH t IN ARRAY ARRAY['projects','project_stages','project_images','project_categories','project_services','project_media_operations'] LOOP
   PERFORM pg_temp.ok(r||' no direct access '||t,NOT has_table_privilege(r,'public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'));
  END LOOP;
  FOREACH s IN ARRAY ARRAY['bedos_project_read(uuid,text,uuid,text,jsonb)','bedos_project_mutate(uuid,text,text,uuid,uuid,integer,jsonb)','bedos_project_media(uuid,text,uuid,uuid,uuid,integer,jsonb,uuid,jsonb)'] LOOP
   PERFORM pg_temp.ok(r||' endpoint ACL '||s,has_function_privilege(r,'public.'||s,'EXECUTE')=(r='service_role'));
  END LOOP;
  FOREACH s IN ARRAY ARRAY['bedos_project_actor(uuid,boolean,boolean)','bedos_project_input(jsonb,text,boolean)','bedos_project_lock(uuid,uuid,integer)','bedos_project_projection(public.projects,boolean,boolean)'] LOOP
   PERFORM pg_temp.ok(r||' helper private '||s,NOT has_function_privilege(r,'public.'||s,'EXECUTE'));
  END LOOP;
 END LOOP;
 PERFORM pg_temp.fails('customer view permission does not allow management',format('SELECT public.bedos_project_read(%L)',customer),'42501');
 PERFORM pg_temp.fails('finance management denied',format('SELECT public.bedos_project_read(%L)',finance),'42501');
 PERFORM pg_temp.fails('inactive management denied',format('SELECT public.bedos_project_read(%L)',inactive),'42501');
 PERFORM pg_temp.fails('anonymous mutation denied','SELECT public.bedos_project_mutate(NULL,''project'',''create'',p_input:=''{}'')','42501');
 res:=public.bedos_project_mutate(a,'category','create',p_input:='{"name":"Construction","slug":"construction"}');c:=(res->>'id')::uuid;
 PERFORM pg_temp.ok('category version defaults',res->>'version'='1');
 res:=public.bedos_project_mutate(cm,'project','create',p_input:=jsonb_build_object('title',' Portfolio ','slug','portfolio','category_id',c,'client_name','Private Client'));p:=(res->>'id')::uuid;
 PERFORM pg_temp.ok('draft defaults normalized and progress unknown',res->>'status'='draft' AND res->>'title'='Portfolio' AND res->>'version'='1' AND res->'progress'='null');
 res:=public.bedos_project_mutate(a,'project','create',p_input:='{"title":"Other","slug":"other"}');other:=(res->>'id')::uuid;
 PERFORM pg_temp.ok('drafts hidden',public.bedos_project_read()->'pagination'->>'total'='0');
 PERFORM pg_temp.fails('draft detail hidden',format('SELECT public.bedos_project_read(p_id:=%L)',p),'P0002');
 PERFORM pg_temp.fails('category deletion restricted',format('SELECT public.bedos_project_mutate(%L,''category'',''delete'',%L,p_version:=1)',a,c),'23503');
 FOREACH s IN ARRAY ARRAY['{"status":"ongoing"}','{"progress":100}','{"title":2}','{"start_date":"2026-02-29"}','{"start_date":"0000-01-01"}','{"slug":"Bad Slug"}','{"service_ids":[null]}','[]','null'] LOOP
  PERFORM pg_temp.fails('strict project fields '||s,format('SELECT public.bedos_project_mutate(%L,''project'',''update'',%L,p_version:=1,p_input:=%L)',a,p,s),'22023');
 END LOOP;
 PERFORM pg_temp.fails('expected version required',format('SELECT public.bedos_project_mutate(%L,''project'',''update'',%L,p_input:=''{}'')',a,p),'22023');
 res:=public.bedos_project_mutate(a,'status','update',p,p_version:=1,p_input:='{"status":"ongoing"}');
 PERFORM pg_temp.ok('ongoing publishes version 2',res->>'version'='2');
 res:=public.bedos_project_read(p_id:=p);PERFORM pg_temp.ok('public excludes private fields',NOT(res ? 'client_name' OR res ? 'created_by' OR res ? 'version') AND res->>'status'='ongoing');
 PERFORM pg_temp.fails('stale project mutation',format('SELECT public.bedos_project_mutate(%L,''project'',''update'',%L,p_version:=1,p_input:=''{}'')',a,p),'P0001');
 res:=public.bedos_project_read(p_query:=jsonb_build_object('page',2,'category_id',c));PERFORM pg_temp.ok('empty page retains count',res->'pagination'->>'total'='1' AND res->'records'='[]');
 PERFORM pg_temp.fails('public draft filter rejected','SELECT public.bedos_project_read(p_query:='' {"status":"draft"}'')','22023');
 PERFORM pg_temp.fails('completion requires stages',format('SELECT public.bedos_project_mutate(%L,''status'',''update'',%L,p_version:=2,p_input:='' {"status":"completed","completion_date":"2026-11-02"}'')',a,p),'P0001');
 res:=public.bedos_project_mutate(cm,'stage','create',p_project:=p,p_version:=2,p_input:='{"name":"Foundation","stage_order":0}');stage:=(res->'stages'->0->>'id')::uuid;
 PERFORM pg_temp.ok('new pending stage advances parent',res->>'version'='3' AND res->>'progress'='0');
 PERFORM pg_temp.fails('cross project stage denied',format('SELECT public.bedos_project_mutate(%L,''stage'',''update'',%L,%L,1,'' {"name":"Bad"}'')',a,stage,other),'P0002');
 PERFORM pg_temp.fails('stage requires start date',format('SELECT public.bedos_project_mutate(%L,''stage'',''update'',%L,%L,3,'' {"status":"in_progress"}'')',a,stage,p),'23514');
 res:=public.bedos_project_mutate(a,'stage','update',stage,p,3,'{"status":"in_progress","start_date":"2026-01-01"}');
 res:=public.bedos_project_mutate(a,'stage','update',stage,p,4,'{"status":"completed","completion_date":"2026-02-01"}');
 PERFORM pg_temp.ok('completed stage progress 100',res->>'progress'='100');
 res:=public.bedos_project_mutate(a,'stage','create',p_project:=p,p_version:=5,p_input:='{"name":"Roof","stage_order":1}');stage2:=(res->'stages'->1->>'id')::uuid;
 PERFORM pg_temp.ok('equal stage progress 50',res->>'progress'='50');
 res:=public.bedos_project_mutate(a,'reorder','update',p_project:=p,p_version:=6,p_input:=jsonb_build_object('stage_ids',jsonb_build_array(stage2,stage)));
 PERFORM pg_temp.ok('atomic reorder',res->'stages'->0->>'id'=stage2::text AND res->>'version'='7');
 PERFORM pg_temp.fails('foreign reorder denied',format('SELECT public.bedos_project_mutate(%L,''reorder'',''update'',p_project:=%L,p_version:=7,p_input:=%L)',a,p,jsonb_build_object('stage_ids',jsonb_build_array(stage,other))),'P0002');
 res:=public.bedos_project_mutate(a,'stage','update',stage2,p,7,'{"status":"in_progress","start_date":"2026-02-01"}');
 res:=public.bedos_project_mutate(a,'stage','update',stage2,p,8,'{"status":"completed","completion_date":"2026-03-01"}');
 res:=public.bedos_project_mutate(a,'status','update',p,p_version:=9,p_input:='{"status":"completed","completion_date":"2026-04-01"}');
 PERFORM pg_temp.ok('completed project and progress agree',res->>'status'='completed' AND res->>'progress'='100');
 PERFORM pg_temp.fails('completed stages frozen',format('SELECT public.bedos_project_mutate(%L,''stage'',''delete'',%L,%L,10)',a,stage,p),'P0001');
 res:=public.bedos_project_mutate(a,'status','update',p,p_version:=10,p_input:='{"status":"ongoing"}');PERFORM pg_temp.ok('reopen clears completion',res->'completion_date'='null');
 INSERT INTO public.services(name,slug,status) VALUES('Linked Service','linked-service-'||a,'published') RETURNING id INTO svc;
 res:=public.bedos_project_mutate(a,'project','update',p,p_version:=11,p_input:=jsonb_build_object('service_ids',jsonb_build_array(svc)));
 PERFORM pg_temp.ok('public linked service visible',jsonb_array_length(public.bedos_project_read(p_id:=p)->'services')=1);
 PERFORM pg_temp.fails('linked service deletion denied',format('DELETE FROM public.services WHERE id=%L',svc),'23503');
 UPDATE public.services SET status='draft' WHERE id=svc;
 PERFORM pg_temp.ok('unpublished linked service hidden retained',public.bedos_project_read(p_id:=p)->'services'='[]' AND EXISTS(SELECT 1 FROM public.project_services WHERE project_id=p AND service_id=svc));
 proof:=jsonb_build_object('mime','image/png','file_size',100,'sha256',repeat('a',64));data:='{"phase":"before","is_primary":true}';
 res:=public.bedos_project_media(cm,'reserve',p_project:=p,p_version:=12,p_input:=data,p_key:=key,p_proof:=proof);op:=(res->'operation'->>'id')::uuid;image:=(res->'operation'->>'media_id')::uuid;old:=res;
 PERFORM pg_temp.ok('upload intent before metadata',res->>'acquired'='true' AND NOT EXISTS(SELECT 1 FROM public.project_images WHERE id=image));
 res:=public.bedos_project_media(cm,'reserve',p_project:=p,p_version:=12,p_input:=data,p_key:=key,p_proof:=proof);PERFORM pg_temp.ok('idempotent replay identical operation',res->'operation'->>'id'=op::text AND res->>'acquired'='false');
 PERFORM pg_temp.fails('idempotency conflict',format('SELECT public.bedos_project_media(%L,''reserve'',p_project:=%L,p_version:=12,p_input:='' {"phase":"after"}'',p_key:=%L,p_proof:=%L)',cm,p,key,proof),'P0001');
 PERFORM pg_temp.fails('pending file hidden',format('SELECT public.bedos_project_media(NULL,''proof'',p_project:=%L,p_media:=%L)',p,image),'P0002');
 res:=public.bedos_project_media(cm,'finalize',p_operation:=op,p_version:=1,p_proof:=jsonb_build_object('lease_token',old->'operation'->>'lease_token'));
 PERFORM pg_temp.ok('finalized image primary and phase',EXISTS(SELECT 1 FROM public.project_images WHERE id=image AND is_primary AND phase='before') AND (SELECT version FROM public.projects WHERE id=p)=14);
 PERFORM pg_temp.ok('public file proof has owned immutable path',public.bedos_project_media(NULL,'proof',p_project:=p,p_media:=image)->>'sha256'=repeat('a',64));
 res:=public.bedos_project_read(p_id:=p);PERFORM pg_temp.ok('public gallery never leaks storage paths',NOT(res->'images'->0 ? 'storage_path') AND res->'images'->0 ? 'image_url');
 PERFORM pg_temp.fails('parent deletion blocked by files',format('SELECT public.bedos_project_mutate(%L,''project'',''delete'',%L,p_version:=14)',a,p),'P0001');
 PERFORM pg_temp.fails('cross-parent image edit',format('SELECT public.bedos_project_media(%L,''update'',p_project:=%L,p_media:=%L,p_version:=1,p_input:='' {"phase":"after"}'')',cm,other,image),'P0002');
 res:=public.bedos_project_media(cm,'update',p_project:=p,p_media:=image,p_version:=14,p_input:='{"phase":"after","is_primary":false}');PERFORM pg_temp.ok('primary invariant retained',EXISTS(SELECT 1 FROM public.project_images WHERE id=image AND is_primary AND phase='after'));
 res:=public.bedos_project_mutate(a,'status','update',p,p_version:=15,p_input:='{"status":"archived"}');
 PERFORM pg_temp.fails('withdrawal blocks old file URL',format('SELECT public.bedos_project_media(NULL,''proof'',p_project:=%L,p_media:=%L)',p,image),'P0002');
 PERFORM pg_temp.ok('staff can preview withdrawal',public.bedos_project_media(cm,'proof',p_project:=p,p_media:=image)->>'mime'='image/png');
 res:=public.bedos_project_media(cm,'delete',p_project:=p,p_media:=image,p_version:=16);old:=res;
 PERFORM pg_temp.ok('delete hides metadata before storage cleanup',res->'operation'->>'state'='cleanup_pending' AND NOT EXISTS(SELECT 1 FROM public.project_images WHERE id=image));
 PERFORM pg_temp.fails('content recovery denied',format('SELECT public.bedos_project_media(%L,''retry'',p_operation:=%L)',cm,op),'42501');
 res:=public.bedos_project_media(a,'retry',p_operation:=op);PERFORM pg_temp.ok('live cleanup lease preserved',res->>'acquired'='false');
 UPDATE public.project_media_operations SET lease_until=clock_timestamp()-interval '1 second' WHERE id=op;
 res:=public.bedos_project_media(a,'retry',p_operation:=op);PERFORM pg_temp.ok('expired lease reclaimed',res->>'acquired'='true' AND res->'operation'->>'lease_token'<>old->'operation'->>'lease_token');
 PERFORM pg_temp.fails('old cleanup lease rejected',format('SELECT public.bedos_project_media(%L,''complete'',p_operation:=%L,p_version:=%s,p_proof:=%L)',cm,op,old->'operation'->>'version',jsonb_build_object('lease_token',old->'operation'->>'lease_token')),'P0001');
 res:=public.bedos_project_media(a,'complete',p_operation:=op,p_version:=(res->'operation'->>'version')::integer,p_proof:=jsonb_build_object('lease_token',res->'operation'->>'lease_token'));PERFORM pg_temp.ok('cleanup terminal',res->'operation'->>'state'='deleted');
 SELECT version INTO v FROM public.projects WHERE id=p;
 res:=public.bedos_project_mutate(a,'project','delete',p,p_version:=v);
 PERFORM pg_temp.ok('parent removed after cleanup',NOT EXISTS(SELECT 1 FROM public.projects WHERE id=p) AND NOT EXISTS(SELECT 1 FROM public.project_stages WHERE project_id=p));
 PERFORM pg_temp.ok('terminal immutable provenance retained',EXISTS(SELECT 1 FROM public.project_media_operations WHERE id=op AND project_id IS NULL AND bound_project_id=p AND actor_id=cm AND state='deleted'));
 PERFORM pg_temp.ok('audit retains deleted stage snapshots',EXISTS(SELECT 1 FROM public.audit_logs WHERE entity_id=p AND action='project_project_delete' AND jsonb_array_length(metadata->'before'->'stages')=2));
 -- Two ready images, replacement/removal and transactional audit rollback.
 res:=public.bedos_project_media(a,'reserve',p_project:=other,p_version:=1,p_input:='{"phase":"before"}',p_key:=gen_random_uuid(),p_proof:=proof);op:=(res->'operation'->>'id')::uuid;image:=(res->'operation'->>'media_id')::uuid;
 res:=public.bedos_project_media(a,'finalize',p_operation:=op,p_version:=1,p_proof:=jsonb_build_object('lease_token',res->'operation'->>'lease_token'));
 res:=public.bedos_project_media(a,'reserve',p_project:=other,p_version:=3,p_input:='{"phase":"after","is_primary":true}',p_key:=gen_random_uuid(),p_proof:=proof);op2:=(res->'operation'->>'id')::uuid;image2:=(res->'operation'->>'media_id')::uuid;
 res:=public.bedos_project_media(a,'finalize',p_operation:=op2,p_version:=1,p_proof:=jsonb_build_object('lease_token',res->'operation'->>'lease_token'));
 PERFORM pg_temp.ok('primary replacement atomic',EXISTS(SELECT 1 FROM public.project_images WHERE id=image2 AND is_primary) AND NOT EXISTS(SELECT 1 FROM public.project_images WHERE id=image AND is_primary));
 res:=public.bedos_project_media(a,'delete',p_project:=other,p_media:=image2,p_version:=5);
 PERFORM pg_temp.ok('deleting primary promotes ordered ready sibling',EXISTS(SELECT 1 FROM public.project_images WHERE id=image AND is_primary));
 SELECT count(*) INTO audits FROM public.audit_logs WHERE entity_id=other;
 PERFORM set_config('bedos.project_fail_action','project_project_update',true);
 PERFORM pg_temp.fails('audit failure aborts project write',format('SELECT public.bedos_project_mutate(%L,''project'',''update'',%L,p_version:=6,p_input:='' {"title":"Uncommitted"}'')',a,other),'23514');
 PERFORM set_config('bedos.project_fail_action','',true);
 PERFORM pg_temp.ok('audit rollback preserves version title and audit count',(SELECT version=6 AND title='Other' FROM public.projects WHERE id=other) AND (SELECT count(*) FROM public.audit_logs WHERE entity_id=other)=audits);
 res:=public.bedos_project_mutate(a,'stage','create',p_project:=other,p_version:=6,p_input:='{"name":"Date boundary","stage_order":0}');stage:=(res->'stages'->0->>'id')::uuid;
 res:=public.bedos_project_mutate(a,'stage','update',stage,other,7,'{"status":"in_progress","start_date":"2026-01-01"}');
 PERFORM pg_temp.fails('completed stage date cannot be null',format('SELECT public.bedos_project_mutate(%L,''stage'',''update'',%L,%L,8,'' {"status":"completed","completion_date":null}'')',a,stage,other),'23514');
END;$test$;
SELECT jsonb_build_object('assertions',count(*),'checks',jsonb_agg(name ORDER BY name)) FROM project_checks;
